import * as T from './vendor/three.module.js';
const P=Math.PI;
function mesh(vertices,uv=[],colors=[]){const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(vertices,3));if(uv.length)g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));if(colors.length)g.setAttribute('color',new T.Float32BufferAttribute(colors,3));g.computeVertexNormals();g.computeBoundingSphere();return g;}
export function sculptedRoof(hip=false){const v=[],uv=[],colors=[],n=12,height=(x,z)=>{const rise=hip?Math.max(0,Math.min(1-Math.abs(x)/.56,(.56-Math.abs(z))/.28)):Math.max(0,1-Math.abs(x)/.56);return .46*Math.pow(rise,.86);};
 function triangle(a,b,c,shade){const ab=new T.Vector3(...b).sub(new T.Vector3(...a)),ac=new T.Vector3(...c).sub(new T.Vector3(...a));if(ab.cross(ac).y<0)[b,c]=[c,b];for(const p of[a,b,c]){v.push(...p);uv.push(p[0]/1.12+.5,p[2]/1.12+.5);colors.push(shade,shade,shade);}}
 // Each shingle is an actual raised surface with a visible lip. The whole roof is one shared mesh.
 for(let row=0;row<n;row++)for(let col=0;col<n;col++){const x0=-.56+col*1.12/n,x1=x0+1.12/n,z0=-.56+row*1.12/n,z1=z0+1.12/n,gap=.0007,shade=.91+((row*13+col*7)%11)*.014,a=[x0+gap,height(x0,z0)+.012,z0+gap],b=[x1-gap,height(x1,z0)+.012,z0+gap],c=[x1-gap,height(x1,z1)+.018,z1-gap],d=[x0+gap,height(x0,z1)+.018,z1-gap];triangle(a,b,c,shade);triangle(a,c,d,shade);for(const [p,q]of[[a,b],[b,c],[c,d],[d,a]]){const r=[q[0],q[1]-.012,q[2]],s=[p[0],p[1]-.012,p[2]];for(const t of[p,q,r,p,r,s]){v.push(...t);uv.push(t[0]+.56,t[2]+.56);colors.push(shade*.76,shade*.76,shade*.76);}}}
 return mesh(v,uv,colors);
}
export function organicGeometry(kind='crown'){const g=new T.IcosahedronGeometry(1,kind==='rock'?1:2),p=g.attributes.position,c=[];for(let i=0;i<p.count;i++){let x=p.getX(i),y=p.getY(i),z=p.getZ(i),f=1+.11*Math.sin(x*9+z*4)*Math.cos(y*8)+.06*Math.sin(z*13-y*5);p.setXYZ(i,x*f,y*f,z*f);const shade=.82+(y+1)*.09+.04*Math.sin(x*7+z*3);c.push(shade,shade,shade);}g.setAttribute('color',new T.Float32BufferAttribute(c,3));g.computeVertexNormals();g.computeBoundingSphere();return g;}
export function pineGeometry(){const v=[],uv=[],colors=[];for(let layer=0;layer<6;layer++){const radius=.92-layer*.13,base=-.48+layer*.22,top=base+.65;for(let j=0;j<10;j++){const a=j*P/5,b=(j+1)*P/5,r=radius*(j%2?.91:1),s=radius*(j%2?1:.91);for(const p of[[Math.cos(a)*r,base+(j%3)*.035,Math.sin(a)*r],[.02*Math.sin(layer),top,-.02],[Math.cos(b)*s,base+((j+1)%3)*.035,Math.sin(b)*s]]){v.push(...p);uv.push(p[0],p[2]);const shade=.78+layer*.045+(j%3)*.035;colors.push(shade,shade,shade);}}}return mesh(v,uv,colors);}
export function torsoGeometry(){const points=[[-.5,.65],[-.38,.82],[-.05,.92],[.27,1],[.4,.77],[.5,.43]].map(([y,r])=>new T.Vector2(r,y)),g=new T.LatheGeometry(points,12);g.computeVertexNormals();return g;}
export function hullGeometry(){const v=[],uv=[],rings=[[-1.35,.04,.07],[-1.05,.32,-.13],[-.6,.45,-.26],[.5,.45,-.26],[1.03,.27,-.12],[1.4,.015,.12]];for(let k=0;k<rings.length-1;k++){const[z,w,b]=rings[k],[zz,ww,bb]=rings[k+1];for(const side of[-1,1]){const a=[side*w,.28,z],c=[side*ww,.28,zz],d=[side*ww*.4,bb,zz],e=[side*w*.4,b,z];for(const face of side<0?[[a,c,d],[a,d,e]]:[[c,a,e],[c,e,d]])for(const p of[face[1],face[0],face[2]]){v.push(...p);uv.push(p[2]*.5,p[1]);}}const a=[-w*.4,b,z],c=[w*.4,b,z],d=[ww*.4,bb,zz],e=[-ww*.4,bb,zz];for(const p of[a,c,d,a,d,e]){v.push(...p);uv.push(p[0],p[2]);}}return mesh(v,uv);}
export function surfaceNormal(kind){const size=128,data=new Uint8Array(size*size*4),height=(x,y)=>{if(kind==='roof')return Math.sin(y/size*P*16)*.55+(Math.cos(x/size*P*14)>.96?-.4:0);if(kind==='wood')return Math.sin(x*.35+Math.sin(y*.06)*.8)*.3+Math.sin(x*1.7+y*.02)*.07;if(kind==='stone'){const yy=(y+size)%size,row=Math.floor(yy/32),xx=(x+row%2*16+size)%32;return xx<2||yy%32<2?-.7:Math.sin(x*.4+y*.3)*.03;}return Math.sin(x*2.1+y*.7)*Math.cos(y*1.3)*.05;};for(let y=0;y<size;y++)for(let x=0;x<size;x++){const a=height(x-1,y)-height(x+1,y),b=height(x,y-1)-height(x,y+1),normal=new T.Vector3(a,b,1).normalize(),i=(y*size+x)*4;data.set([(normal.x*.5+.5)*255,(normal.y*.5+.5)*255,(normal.z*.5+.5)*255,255],i);}const t=new T.DataTexture(data,size,size);t.wrapS=t.wrapT=T.RepeatWrapping;t.needsUpdate=true;return t;}
export function clothRoof(){const v=[],uv=[];for(const side of[-1,1])for(let i=0;i<8;i++)for(let j=0;j<6;j++){const point=(x,z)=>[side*x,.46*(1-x/.56)-.045*Math.sin(x/.56*Math.PI)*Math.sin((z+.56)/1.12*Math.PI),z],a=point(i*.07,-.56+j*1.12/6),b=point((i+1)*.07,-.56+j*1.12/6),c=point((i+1)*.07,-.56+(j+1)*1.12/6),d=point(i*.07,-.56+(j+1)*1.12/6);for(const face of side>0?[[a,c,b],[a,d,c]]:[[a,b,c],[a,c,d]])for(const p of face){v.push(...p);uv.push(p[0]+.56,p[2]+.56);}}return mesh(v,uv);}
export function cropGeometry(){const v=[],uv=[];for(let i=0;i<7;i++){const a=i*2.4,x=Math.sin(a)*.38,z=Math.cos(a)*.38,h=.6+(i%3)*.2;for(let j=0;j<3;j++){const y=j*h/3,yy=(j+1)*h/3,w=.1*(1-j/3),xx=x+Math.sin(a)*j*.08;for(const p of[[xx-w,y,z],[xx+w,y,z],[xx+w*.6+.04,yy,z+.05],[xx-w,y,z],[xx+w*.6+.04,yy,z+.05],[xx-w*.6+.04,yy,z+.05]]){v.push(...p);uv.push(p[0]+.5,p[1]);}}for(let j=0;j<3;j++)for(const p of[[x-.12,h+j*.06,z],[x+.12,h+j*.06,z],[x,h+.12+j*.06,z+.1]]){v.push(...p);uv.push(p[0]+.5,p[1]);}}return mesh(v,uv);}
export function shoreGeometry(){const v=[],uv=[],colors=[],point=(t,z)=>[t*(.25+.035*Math.sin((z+.5)*Math.PI*2)),-t*t,z];for(let row=0;row<8;row++)for(let col=0;col<4;col++){const a=point(col/4,row/8-.5),b=point((col+1)/4,row/8-.5),c=point((col+1)/4,(row+1)/8-.5),d=point(col/4,(row+1)/8-.5);for(const p of[a,c,b,a,d,c]){v.push(...p);uv.push(p[0],p[2]);const color=new T.Color('#78a455').lerp(new T.Color('#c3b78e'),Math.sqrt(-p[1]));colors.push(color.r,color.g,color.b);}}return mesh(v,uv,colors);}
